import UIKit
final class AIInterpretationViewController:UIViewController {
 override func viewDidLoad(){super.viewDidLoad();title = "2. AI Interpretation";view.backgroundColor = .systemGroupedBackground;let heading = UILabel();heading.text = "SIMULATED AI INTERPRETATION";heading.font = .preferredFont(forTextStyle:.headline);heading.textColor = InterfaceStyle.accent;let text = UILabel();text.text = InterpretationStore.shared.value.text;text.numberOfLines = 0;text.textColor = .white;text.font = .preferredFont(forTextStyle:.title3);let card = InterfaceStyle.glassCard();card.contentView.addSubview(text);text.translatesAutoresizingMaskIntoConstraints = false;card.translatesAutoresizingMaskIntoConstraints = false;NSLayoutConstraint.activate([text.leadingAnchor.constraint(equalTo:card.contentView.leadingAnchor,constant:20),text.trailingAnchor.constraint(equalTo:card.contentView.trailingAnchor,constant:-20),text.topAnchor.constraint(equalTo:card.contentView.topAnchor,constant:20),text.bottomAnchor.constraint(equalTo:card.contentView.bottomAnchor,constant:-20)]);let note = UILabel();note.text = "This predefined response is used only to simulate an AI interpretation for the study.";note.textColor = .secondaryLabel;note.numberOfLines = 0;let next = InterfaceStyle.pillButton("Choose interface mode",symbol:"rectangle.3.group",filled:true);next.addTarget(self,action:#selector(go),for:.touchUpInside);let s = UIStackView(arrangedSubviews:[heading,card,note,next]);s.axis = .vertical;s.spacing = 20;s.translatesAutoresizingMaskIntoConstraints = false;view.addSubview(s);NSLayoutConstraint.activate([s.leadingAnchor.constraint(equalTo:view.layoutMarginsGuide.leadingAnchor),s.trailingAnchor.constraint(equalTo:view.layoutMarginsGuide.trailingAnchor),s.centerYAnchor.constraint(equalTo:view.centerYAnchor)])}
 @objc func go(){navigationController?.pushViewController(ModeSelectionViewController(),animated:true)} }
final class ModeSelectionViewController:UIViewController { override func viewDidLoad(){super.viewDidLoad();title = "3. Interface Mode";view.backgroundColor = .systemGroupedBackground;let label = UILabel();label.text = "How should the assistant present its interpretation?";label.numberOfLines = 0;label.font = .preferredFont(forTextStyle:.title2);let s = UIStackView();s.axis = .vertical;s.spacing = 12;[("2D Conversational","message.fill"),("Screen-Fixed AR","viewfinder"),("Object-Anchored AR","mappin.and.ellipse")].enumerated().forEach{index,item in let b = InterfaceStyle.pillButton(item.0,symbol:item.1,filled:index==0);b.tag = index;b.addTarget(self,action:#selector(open(_:)),for:.touchUpInside);s.addArrangedSubview(b)};let all = UIStackView(arrangedSubviews:[label,s]);all.axis = .vertical;all.spacing = 28;all.translatesAutoresizingMaskIntoConstraints = false;view.addSubview(all);NSLayoutConstraint.activate([all.leadingAnchor.constraint(equalTo:view.layoutMarginsGuide.leadingAnchor),all.trailingAnchor.constraint(equalTo:view.layoutMarginsGuide.trailingAnchor),all.centerYAnchor.constraint(equalTo:view.centerYAnchor)])};@objc func open(_ sender:UIButton){let vc:UIViewController = sender.tag==0 ? ChatViewController() : (sender.tag==1 ? ScreenFixedARViewController() : ObjectAnchoredARViewController());navigationController?.pushViewController(vc,animated:true)} }
